        // ── Background Continuous Monitoring ─────────────────────────────────
        private void StartBackgroundMonitoring()
        {
            try { System.IO.Directory.CreateDirectory(System.IO.Path.GetDirectoryName(BgMonitorLogPath)!); } catch (Exception logEx) { AppLogger.Warning(logEx, "Unhandled exception"); }
            // Write CSV header if new file
            if (!System.IO.File.Exists(BgMonitorLogPath))
            {
                try { System.IO.File.WriteAllText(BgMonitorLogPath, "Timestamp,CpuTemp,GpuTemp,CpuPct,RamMB\n"); } catch (Exception logEx) { AppLogger.Warning(logEx, "Unhandled exception"); }
            }
            _bgMonitorTimer.Interval = TimeSpan.FromSeconds(30);
            _bgMonitorTimer.Tick += OnBgMonitorTick;
            _bgMonitorTimer.Start();
            StartRamHistory();
        }

        private void InitDataProvider()
        {
            _dataProvider.GetCpuPct  = () => _cachedCpuPct >= 0 ? _cachedCpuPct : 0f;
            _dataProvider.GetCpuTemp = () => _lastTempSnap?.CpuTemp ?? -1f;
            _dataProvider.GetGpuData = () =>
            {
                float pct  = _cachedGpuPct >= 0 ? _cachedGpuPct : -1f;
                float temp = _lastTempSnap?.GpuTemp ?? -1f;
                return (pct, temp, -1f, 0u);
            };
            _dataProvider.GetRam = () =>
            {
                float total = _cachedTotalRamMB;
                float avail = _cachedAvailRamMB;
                float used  = total > 0 && avail >= 0 ? total - avail : -1f;
                return (used, total);
            };
            _dataProvider.DispatcherInvoke = action => Dispatcher.InvokeAsync(action).Task;
        }

        private async void OnBgMonitorTick(object? sender, EventArgs e)
        {
            if (_monitoringPausedForScan) return;
            try
            {
                float cpuTemp = 0, gpuTemp = 0, cpuPct = 0, ramMB = 0;
                await Task.Run(() =>
                {
                    try
                    {
                        if (_tempReader != null)
                        {
                            var snap = _tempReader.Read();
                            // an old snapshot (lock busy / read blocked) does not count towards the maxima
                            if (snap.IsFresh(TimeSpan.FromSeconds(10)))
                            {
                                cpuTemp = snap.CpuTemp ?? 0;
                                gpuTemp = snap.GpuTemp ?? 0;
                            }
                        }
                        // CPU % via perf counter cached value
                        cpuPct = _cachedCpuPct > 0 ? _cachedCpuPct : 0;
                        // RAM via PerformanceCounter (already available)
                        try
                        {
                            using var ramSearcher = SMDWin.Services.WmiHelper.Searcher(
"SELECT FreePhysicalMemory, TotalVisibleMemorySize FROM Win32_OperatingSystem");
                            using (var __wmiTmp1 = ramSearcher.Get())
                            {
                                foreach (System.Management.ManagementObject obj in __wmiTmp1)
                            {
                                ulong free  = obj["FreePhysicalMemory"]  is ulong f ? f : 0;
                                ulong total = obj["TotalVisibleMemorySize"] is ulong t ? t : 0;
                                if (total > 0) ramMB = (float)((total - free) / 1024.0);
                                break;
                            }
                            }
                        }
                        catch (Exception ex) { AppLogger.Warning(ex, "MainWindow.OnBgMonitorTick"); }
                    }
                    catch (Exception ex) { AppLogger.Warning(ex, "MainWindow.OnBgMonitorTick"); }
                });

                // Track session maxima
                if (cpuTemp > 0) _bgMaxCpuTemp = Math.Max(_bgMaxCpuTemp, cpuTemp);
                if (gpuTemp > 0) _bgMaxGpuTemp = Math.Max(_bgMaxGpuTemp, gpuTemp);
                if (cpuPct  > 0) _bgMaxCpuPct  = Math.Max(_bgMaxCpuPct,  cpuPct);
                if (ramMB   > 0) _bgMaxRamMB   = Math.Max(_bgMaxRamMB,   ramMB);
                _bgSampleCount++;

                // Append to the CSV log (skipped if the app is closing — avoids corrupting the file)
                if (!_appExiting)
                {
                    var line = $"{DateTime.Now:yyyy-MM-dd HH:mm:ss},{cpuTemp:F1},{gpuTemp:F1},{cpuPct:F1},{ramMB:F0}\n";
                    try { System.IO.File.AppendAllText(BgMonitorLogPath, line); } catch (Exception logEx) { AppLogger.Warning(logEx, "System.IO.File.AppendAllText(BgMonitorLogPath, line);"); }
                }

                // Temperature warning notification (if temp exceeds threshold and ShowTempNotif is on)
                if (SettingsService.Current.EnableNotifications)
                {
                    if (cpuTemp >= SettingsService.Current.TempWarnCpu && cpuTemp > 0)
                        ShowToastWarning(string.Format(_LS("Stress", "CpuHotFmt"), $"{cpuTemp:F0}"));
                    else if (gpuTemp >= SettingsService.Current.TempWarnGpu && gpuTemp > 0)
                        ShowToastWarning(string.Format(_LS("Stress", "GpuHotFmt"), $"{gpuTemp:F0}"));
                }

                // ── SIDEBAR BADGES — live alert indicators ────────────────────
                // Temp badge: show when CPU or GPU is hot (>= warn threshold)
                bool cpuTempAlert = cpuTemp > 0 && cpuTemp >= SettingsService.Current.TempWarnCpu;
                bool gpuTempAlert = gpuTemp > 0 && gpuTemp >= SettingsService.Current.TempWarnGpu;
                bool tempAlert = cpuTempAlert || gpuTempAlert;
                int severityLevel = ((cpuTemp >= 90 || gpuTemp >= 90) && tempAlert) ? 2 : (tempAlert ? 1 : 0);

                bool stressRunning = _cpuStress.Running || _gpuStress.IsRunning;
                if (stressRunning) _cpuHighCount = 0;
                else if (cpuPct >= 95f) _cpuHighCount++;
                else _cpuHighCount = Math.Max(0, _cpuHighCount - 1);
                // ~30 s at default 5 s interval = 6 samples; show badge after 6 consecutive
                bool cpuSustained = _cpuHighCount >= 6;
                if (cpuSustained) severityLevel = Math.Max(severityLevel, 1);

                // Real count of concurrent problems (0-3), not a severity level.
                int tempIssueCount = (cpuTempAlert ? 1 : 0) + (gpuTempAlert ? 1 : 0) + (cpuSustained ? 1 : 0);
                bool newTempActive = tempIssueCount > 0;

                var tempReasons = new List<string>();
                if (cpuTempAlert)
                    tempReasons.Add(cpuTemp >= 90
                        ? string.Format(_LS("Notif", "CpuTempReasonCritical"), cpuTemp.ToString("F0"))
                        : string.Format(_LS("Notif", "CpuTempReasonWarn"), cpuTemp.ToString("F0"), SettingsService.Current.TempWarnCpu.ToString("F0")));
                if (gpuTempAlert)
                    tempReasons.Add(gpuTemp >= 90
                        ? string.Format(_LS("Notif", "GpuTempReasonCritical"), gpuTemp.ToString("F0"))
                        : string.Format(_LS("Notif", "GpuTempReasonWarn"), gpuTemp.ToString("F0"), SettingsService.Current.TempWarnGpu.ToString("F0")));
                if (cpuSustained)
                    tempReasons.Add(_LS("Notif", "CpuSustainedReason"));
                string tempReason = string.Join(" · ", tempReasons);

                if (newTempActive && !_badgeTempActive)
                {
                    UpdateSidebarBadge("Temp", tempIssueCount, tempReason, severityLevel);
                    _badgeTempLastSeenUtc = DateTime.UtcNow;
                    if (!string.IsNullOrEmpty(tempReason))
                        RecordLastAlert(tempReason);
                }
                else if (newTempActive && (tempIssueCount > _lastTempBadgeCount || severityLevel > _lastTempBadgeLevel))
                {
                    // Escalation (more problems or higher severity) while the alert is still active
                    UpdateSidebarBadge("Temp", tempIssueCount, tempReason, severityLevel);
                    _badgeTempLastSeenUtc = DateTime.UtcNow;
                    if (!string.IsNullOrEmpty(tempReason)) RecordLastAlert(tempReason);
                }
                else if (newTempActive)
                {
                    _badgeTempLastSeenUtc = DateTime.UtcNow;
                }
                _badgeTempActive = newTempActive;
                if (tempIssueCount > _lastTempBadgeCount) _lastTempBadgeCount = tempIssueCount;
                if (severityLevel > _lastTempBadgeLevel) _lastTempBadgeLevel = severityLevel;

                // Disk health badge: worst disk < 80% health
                if (!_badgeDiskActive)
                {
                    var worstDisk = _allDisks
                        .Where(d => d.HealthPercent > 0 && d.HealthPercent < 80)
                        .OrderBy(d => d.HealthPercent)
                        .FirstOrDefault();
                    if (worstDisk != null)
                    {
                        _badgeDiskActive = true;
                        string smartReason = SMDWin.Services.HardwareService.GetDiskHealthReason(worstDisk);
                        string diskReason = $"{worstDisk.Model}: {worstDisk.HealthPercent}% health"
                            + (string.IsNullOrEmpty(smartReason) ? "" : $" — {smartReason}");
                        UpdateSidebarBadge("Disk", 1, diskReason);
                        SMDWin.Services.NotificationCenter.Add(SMDWin.Services.NotifCategory.Disk,
                            worstDisk.HealthPercent < 50 ? SMDWin.Services.NotifSeverity.Critical : SMDWin.Services.NotifSeverity.Warning,
                            diskReason);
                    }
                }

                // Battery health badge: health < 50%  (only once per run, health doesn't change live)
                if (!_badgeBatteryActive && _batteryWearPct >= 0)
                {
                    int health = Math.Max(0, 100 - _batteryWearPct);
                    if (health > 0 && health < 50) { _badgeBatteryActive = true; UpdateSidebarBadge("Battery", 1); }
                }
            }
            catch (Exception ex) { AppLogger.Warning(ex, "MainWindow.unknown"); }
        }

        private void StartPerfCounterThread()
        {
            if (_perfPollRunning) return;
            _perfPollRunning = true;
            _perfPollThread = new System.Threading.Thread(() =>
            {
                // Init CPU counter on background thread — first call can block 200ms+
                // "% Processor Utility" (Processor Information category) matches Task Manager exactly.
                // Falls back to "% Processor Time" if Processor Information is unavailable (older OS).
                try
                {
                    _cpuPerfCounter = new System.Diagnostics.PerformanceCounter(
                        "Processor Information", "% Processor Utility", "_Total");
                    _cpuPerfCounter.NextValue(); // prime — discarded
                    _cpuPerfCounterName = "Processor Information/% Processor Utility";
                }
                catch
                {
                    // Fallback: older Windows versions may not have "Processor Information"
                    try { _cpuPerfCounter = new System.Diagnostics.PerformanceCounter("Processor", "% Processor Time", "_Total"); _cpuPerfCounterName = "Processor/% Processor Time"; }
                    catch { _cpuPerfCounter = null; _cpuPerfCounterName = "none"; }
                }
                try { _cpuPerfCounter?.NextValue(); } catch (Exception logEx) { AppLogger.Warning(logEx, "_cpuPerfCounter?.NextValue();"); }
                System.Threading.Thread.Sleep(500);
                _cpuCounterPrimed = true;

                System.Diagnostics.PerformanceCounter? pcRamAvail = null;
                System.Diagnostics.PerformanceCounter? pcRamCommitted = null;
                System.Diagnostics.PerformanceCounter? pcRamCached = null;
                try { pcRamAvail     = new System.Diagnostics.PerformanceCounter("Memory", "Available MBytes"); } catch (Exception ex) { AppLogger.Debug(ex.Message); }
                try
                {
                    pcRamCommitted = new System.Diagnostics.PerformanceCounter("Memory", "Committed Bytes");
                    pcRamCommitted.NextValue(); // discard
                }
                catch (Exception ex) { AppLogger.Debug(ex.Message); }
                try
                {
                    pcRamCached = new System.Diagnostics.PerformanceCounter("Memory", "Cache Bytes");
                    pcRamCached.NextValue(); // discard
                }
                catch (Exception ex) { AppLogger.Debug(ex.Message); }

                try
                {
                    using var ramTotal = SMDWin.Services.WmiHelper.Searcher(
                        "SELECT TotalVisibleMemorySize FROM Win32_OperatingSystem");
                    using (var __wmiTmp2 = ramTotal.Get())
                    {
                        foreach (System.Management.ManagementObject o in __wmiTmp2)
                    {
                        _cachedTotalRamMB = Convert.ToSingle(o["TotalVisibleMemorySize"]) / 1024f;
                        break;
                    }
                    }
                }
                catch (Exception ex) { AppLogger.Warning(ex, "MainWindow.StartPerfCounterThread"); }

                while (_perfPollRunning)
                {
                    bool windowVisible = _uiVisibleCached;
                    int sleepMs = windowVisible ? 1000 : _hiddenPollMs;

                    try
                    {
                        bool cpuStressOn = _cpuStress.Running;
                        // during stress the load read comes before the stress threads (which are at most "below normal")
                        var wantPriority = cpuStressOn ? System.Threading.ThreadPriority.AboveNormal
                                                        : System.Threading.ThreadPriority.BelowNormal;
                        if (_perfPollThread != null && _perfPollThread.Priority != wantPriority)
                            _perfPollThread.Priority = wantPriority;

                        if (cpuStressOn)
                        {
                            _perfPollBoostTickCount++;
                            if (_perfPollBoostTickCount >= 10)
                            {
                                _perfPollBoostTickCount = 0;
                                float? lhmLoad = _lastTempSnap?.CpuLoadPct;
                                AppLogger.Info(
                                    "S3-DIAG-LOAD displayed(PerfCounter,{0})={1}%  lhm(TempReader)={2}%  threadPriority={3}",
                                    _cpuPerfCounterName, _cachedCpuPct.ToString("F0"),
                                    lhmLoad.HasValue ? lhmLoad.Value.ToString("F0") : "null",
                                    _perfPollThread?.Priority);
                            }
                        }
                        else _perfPollBoostTickCount = 0;
                    }
                    catch (Exception exPr) { AppLogger.Debug(exPr.Message); }

                    try
                    {
                        // CPU usage
                        if (_cpuPerfCounter != null && _cpuCounterPrimed)
                        {
                            float rawCpu = _cpuPerfCounter.NextValue();
                            // SELF-HEAL: PDH returned EXACTLY the same non-zero raw value for dozens of consecutive reads = a corrupt counter
                            // (happens after sleep/resume or when the performance service resets). On a live system % Processor Time always has
                            // different decimals between samples — bit-for-bit equality 60 times in a row is practically impossible.
                            // The counter is recreated from scratch.
                            if (rawCpu > 0.5f && rawCpu == _lastRawCpuPct) _rawCpuStuckCount++;
                            else _rawCpuStuckCount = 0;
                            _lastRawCpuPct = rawCpu;
                            if (_rawCpuStuckCount >= 60)
                            {
                                _rawCpuStuckCount = 0;
                                AppLogger.Warning($"CPU PerfCounter stuck at {rawCpu:F2}% for 60 consecutive reads — recreating the counter.");
                                try { _cpuPerfCounter.Dispose(); } catch (Exception exd) { AppLogger.Debug(exd.Message); }
                                _cpuPerfCounter = null;
                                try
                                {
                                    _cpuPerfCounter = new System.Diagnostics.PerformanceCounter("Processor", "% Processor Time", "_Total");
                                    _cpuPerfCounter.NextValue(); // prime
                                }
                                catch (Exception exr) { AppLogger.Warning(exr, "PerfCounter CPU recreate"); }
                            }
                            else
                            {
                                _cachedCpuPct = Math.Max(0f, Math.Min(100f, rawCpu));
                            }
                        }

                        // GPU — lazy-init on background thread
                        if (!_gpuCountersInitialized)
                        {
                            // If a reinit delay is set (after a complete crash), wait
                            if (_gpuReinitDelayTicks > 0)
                            {
                                _gpuReinitDelayTicks--;
                            }
                            else
                            {
                            _gpuCountersInitialized = true;
                            _gpuCounters = new List<System.Diagnostics.PerformanceCounter>();
                            try
                            {
                                // Task Manager reads GPU utilization from "GPU Engine" % Utilization
                                // summed across engine types per adapter LUID.
                                // Strategy: collect one counter per engine type using the luid_*_phys_0_* pattern,
                                // then sum at read time — this matches Task Manager's "3D + Compute + Copy" total.
                                var cat = new System.Diagnostics.PerformanceCounterCategory("GPU Engine");
                                var instances = cat.GetInstanceNames();

                                // Group by LUID (pid=0 instances represent the adapter totals per engine type)
                                // Instance name format: luid_0x0000..._phys_0_eng_0_engtype_3D
                                // We want one entry per engine TYPE per adapter (not per-process)
                                var adapterInstances = instances
                                    .Where(n => n.Contains("pid_0_", StringComparison.OrdinalIgnoreCase) &&
                                               (n.Contains("engtype_3D",          StringComparison.OrdinalIgnoreCase) ||
                                                n.Contains("engtype_Compute",      StringComparison.OrdinalIgnoreCase) ||
                                                n.Contains("engtype_Copy",         StringComparison.OrdinalIgnoreCase) ||
                                                n.Contains("engtype_VideoDecode",  StringComparison.OrdinalIgnoreCase) ||
                                                n.Contains("engtype_VideoEncode",  StringComparison.OrdinalIgnoreCase)))
                                    .Take(20)
                                    .ToArray();

                                // If pid_0 pattern not found → Intel iGPU fallback.
                                // We pre-build counters here (once at init) and do a single Sleep(100)
                                // so they are primed and ready for immediate NextValue() in the hot loop.
                                // This avoids the per-tick Sleep(50)*N pattern that caused 40% CPU.
                                if (adapterInstances.Length == 0)
                                {
                                    _gpuFallbackMode = true;
                                    adapterInstances = instances
                                        .Where(n => n.Contains("engtype_3D",         StringComparison.OrdinalIgnoreCase) ||
                                                    n.Contains("engtype_Compute",     StringComparison.OrdinalIgnoreCase) ||
                                                    n.Contains("engtype_Copy",        StringComparison.OrdinalIgnoreCase))
                                        .Take(16)
                                        .ToArray();
                                }

                                foreach (var inst in adapterInstances)
                                {
                                    try
                                    {
                                        var c = new System.Diagnostics.PerformanceCounter("GPU Engine", "Utilization Percentage", inst);
                                        c.NextValue(); // prime
                                        _gpuCounters.Add(c);

                                        // Separate counters for encode/decode
                                        if (inst.Contains("engtype_VideoEncode", StringComparison.OrdinalIgnoreCase))
                                        {
                                            _gpuEncodeCounters ??= new();
                                            var ce = new System.Diagnostics.PerformanceCounter("GPU Engine", "Utilization Percentage", inst);
                                            ce.NextValue();
                                            _gpuEncodeCounters.Add(ce);
                                        }
                                        else if (inst.Contains("engtype_VideoDecode", StringComparison.OrdinalIgnoreCase))
                                        {
                                            _gpuDecodeCounters ??= new();
                                            var cd = new System.Diagnostics.PerformanceCounter("GPU Engine", "Utilization Percentage", inst);
                                            cd.NextValue();
                                            _gpuDecodeCounters.Add(cd);
                                        }
                                    }
                                    catch (Exception ex) { AppLogger.Warning(ex, "MainWindow.unknown"); }
                                }

                                // Single sleep after priming all counters — only at init, never in hot loop
                                if (_gpuCounters.Count > 0)
                                    System.Threading.Thread.Sleep(100);
                            }
                            catch { _gpuCounters = null; }
                            } // end else (delay == 0)
                        }

                        // Sum utilization across engine types (clamped to 100%) — matches Task Manager.
                        if (_gpuCounters != null && _gpuCounters.Count > 0)
                        {
                            float gpuSum = 0;
                            var   toRemove = new List<System.Diagnostics.PerformanceCounter>();

                            foreach (var c in _gpuCounters)
                            {
                                try
                                {
                                    gpuSum += c.NextValue();
                                }
                                catch
                                {
                                    // Invalid counter (process died, driver reset) — mark for removal.
                                    // Not logged — it would generate thousands of lines per day.
                                    toRemove.Add(c);
                                }
                            }

                            // Remove the dead counters from the list
                            if (toRemove.Count > 0)
                            {
                                foreach (var dead in toRemove)
                                {
                                    _gpuCounters.Remove(dead);
                                    try { dead.Dispose(); } catch (Exception ex) { AppLogger.Debug(ex.Message); }
                                }

                                // If all counters have failed → reinitialize on the next tick
                                // (GPU driver reset, sleep/wake, driver update, etc.)
                                if (_gpuCounters.Count == 0)
                                {
                                    AppLogger.Warning("GPU counter: all counters invalid — will reinitialize");
                                    _gpuCounters = null;
                                    _gpuCountersInitialized = false;
                                    // Wait 5 seconds before reinitializing, so it does not cycle rapidly if the GPU is unstable
                                    _gpuReinitDelayTicks = 5;
                                }
                            }

                            _cachedGpuPct = Math.Max(0f, Math.Min(100f, gpuSum));

                            // Encode/Decode separate
                            if (_gpuEncodeCounters?.Count > 0)
                            {
                                float enc = 0;
                                foreach (var c in _gpuEncodeCounters) try { enc += c.NextValue(); } catch (Exception ex) { AppLogger.Debug(ex.Message); }
                                _cachedGpuEncodePct = Math.Clamp(enc, 0f, 100f);
                            }
                            if (_gpuDecodeCounters?.Count > 0)
                            {
                                float dec = 0;
                                foreach (var c in _gpuDecodeCounters) try { dec += c.NextValue(); } catch (Exception ex) { AppLogger.Debug(ex.Message); }
                                _cachedGpuDecodePct = Math.Clamp(dec, 0f, 100f);
                            }
                        }

                        if (pcRamAvail != null)
                            try { _cachedAvailRamMB = pcRamAvail.NextValue(); } catch (Exception logEx) { AppLogger.Warning(logEx, "_cachedAvailRamMB"); }
                        if (pcRamCommitted != null)
                            try { _cachedCommittedRamMB = pcRamCommitted.NextValue() / 1024f / 1024f; } catch (Exception ex) { AppLogger.Debug(ex.Message); }
                        if (pcRamCached != null)
                            try { _cachedCachedRamMB = pcRamCached.NextValue() / 1024f / 1024f; } catch (Exception ex) { AppLogger.Debug(ex.Message); }

                        // Processes / Threads / Handles — System performance counters
                        try
                        {
                            var procs = System.Diagnostics.Process.GetProcesses();
                            _cachedProcessCount = procs.Length;
                            int threads = 0, handles = 0;
                            foreach (var p in procs)
                            {
                                try { threads += p.Threads.Count; } catch (Exception ex) { AppLogger.Debug(ex.Message); }
                                try { handles += p.HandleCount;   } catch (Exception ex) { AppLogger.Debug(ex.Message); }
                                finally { p.Dispose(); }
                            }
                            _cachedThreadCount = threads;
                            _cachedHandleCount = handles;
                        }
                        catch (Exception ex) { AppLogger.Debug(ex.Message); }
                    }
                    catch (Exception ex) { AppLogger.Warning(ex, "MainWindow.unknown"); }

                    try { System.Threading.Thread.Sleep(sleepMs); }
                    catch (System.Threading.ThreadInterruptedException) { break; } // clean exit on Stop()
                }
                try { pcRamAvail?.Dispose(); } catch (Exception ex) { AppLogger.Debug(ex.Message); }
            })
            { IsBackground = true, Name = "PerfCounterPoller", Priority = System.Threading.ThreadPriority.BelowNormal };
            _perfPollThread.Start();
        }

        private void StopPerfCounterThread()
        {
            _perfPollRunning = false;
            // Interrupt the sleep so the thread exits immediately instead of waiting up to 1s
            try { _perfPollThread?.Interrupt(); } catch (Exception ex) { AppLogger.Debug(ex.Message); }
            // Wait up to 500ms for clean exit — avoids lingering thread in Task Manager
            try { _perfPollThread?.Join(500); } catch (Exception ex) { AppLogger.Debug(ex.Message); }
            try { _cpuPerfCounter?.Dispose(); } catch (Exception ex) { AppLogger.Debug(ex.Message); } _cpuPerfCounter = null;
            if (_gpuCounters != null) { foreach (var c in _gpuCounters) try { c.Dispose(); } catch (Exception ex) { AppLogger.Debug(ex.Message); } }
            _gpuCounters = null;
        }

        // Controls that may be absent from XAML (removed in UI refactor) — kept as null stubs
        // so code-behind references compile without errors
